async function openProcedure(id){const p=await NurseDB.get('procedures',id);if(!p)return;const cases=await NurseDB.all('cases');const exp=cases.flatMap(c=>(c.procedures||[]).filter(x=>x.id===id).map(x=>({...x,date:c.date,diagnosis:c.diagnosis})));modal(`<div class="modal-head"><h2>${esc(p.name)}</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="btn-row"><button class="btn ${p.favorite?'primary':''}" id="favProc">${p.favorite?'★ Favorita':'☆ Favorita'}</button><button class="btn" id="editProc">Editar</button></div><h3>Material</h3><div class="list">${p.materials.map(x=>`<label class="check-row"><input type="checkbox"><span>${esc(x)}</span></label>`).join('')||noData('Sin material definido')}</div><h3>Puntos / notas</h3><div class="notice info">${esc((p.notes||[]).join(' '))}</div>${p.personalNotes?`<p>${esc(p.personalNotes)}</p>`:''}<h3>Mi experiencia</h3><div class="list">${exp.map(x=>`<div class="list-row"><div class="grow"><strong>${esc(x.participation)}</strong><div class="sub">${dateFmt(x.date)} · ${esc(x.diagnosis)}</div></div></div>`).join('')||noData('Sin experiencias registradas')}</div>`);$('#favProc').onclick=async()=>{p.favorite=!p.favorite;await NurseDB.put('procedures',p);closeModal();openProcedure(id)};$('#editProc').onclick=()=>{closeModal();openProcedureEdit(id)}}
async function openProcedureEdit(id){const p=await NurseDB.get('procedures',id);modal(`<div class="modal-head"><h2>Editar técnica</h2><button class="icon-btn" onclick="closeModal()">×</button></div><form id="procEdit"><label>Nombre</label><input class="field" name="name" value="${esc(p.name)}"><label>Material (una línea por elemento)</label><textarea class="field" name="materials">${esc(p.materials.join('\n'))}</textarea><label>Notas personales / protocolo de tu unidad</label><textarea class="field" name="personal">${esc(p.personalNotes||'')}</textarea><div class="modal-actions"><button class="btn primary">Guardar</button></div></form>`);$('#procEdit').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);p.name=f.get('name').trim();p.materials=f.get('materials').split('\n').map(x=>x.trim()).filter(Boolean);p.personalNotes=f.get('personal').trim();p.updatedAt=new Date().toISOString();await NurseDB.put('procedures',p);closeModal();toast('Técnica actualizada')}}
function openCalculators(){modal(`<div class="modal-head"><h2>Calculadoras</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="list">${[['mlh','Velocidad de infusión','mL/h'],['drops','Ritmo de goteo','gotas/min'],['dose','Dosis por peso','mg o mL'],['bmi','IMC','kg/m²'],['bsa','Superficie corporal','m²'],['balance','Balance hídrico','mL']].map(x=>`<button class="list-row clickable" data-calc="${x[0]}"><div class="avatar">÷</div><div class="grow"><strong>${x[1]}</strong><div class="sub">${x[2]}</div></div><span class="chev">›</span></button>`).join('')}</div>${clinicalNotice()}`);$$('[data-calc]').forEach(b=>b.onclick=()=>openCalc(b.dataset.calc))}
function openCalc(type){const defs={mlh:['Velocidad de infusión',[['vol','Volumen (mL)'],['hours','Tiempo (h)']],'mL/h',(v)=>v.vol/v.hours],drops:['Ritmo de goteo',[['vol','Volumen (mL)'],['minutes','Tiempo (min)'],['factor','Factor de goteo (gotas/mL)']],'gotas/min',(v)=>v.vol*v.factor/v.minutes],dose:['Cálculo de dosis por peso',[['mgkg','Dosis prescrita (mg/kg)'],['kg','Peso (kg)'],['conc','Concentración disponible (mg/mL)']],'mL',(v)=>v.mgkg*v.kg/v.conc],bmi:['Índice de masa corporal',[['kg','Peso (kg)'],['m','Talla (m)']],'kg/m²',(v)=>v.kg/(v.m*v.m)],bsa:['Superficie corporal (Mosteller)',[['kg','Peso (kg)'],['cm','Talla (cm)']],'m²',(v)=>Math.sqrt(v.kg*v.cm/3600)],balance:['Balance hídrico',[['in','Entradas (mL)'],['out','Salidas (mL)']],'mL',(v)=>v.in-v.out]};const d=defs[type];modal(`<div class="modal-head"><h2>${d[0]}</h2><button class="icon-btn" onclick="closeModal()">×</button></div><form id="calcForm">${d[1].map(([n,l])=>`<label>${l}</label><input class="field" type="number" step="any" name="${n}" required>`).join('')}<div id="calcResult"></div><div class="modal-actions"><button class="btn primary">Calcular</button></div></form>${clinicalNotice()}`);$('#calcForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v={};d[1].forEach(([n])=>v[n]=Number(f.get(n)));const r=d[3](v);$('#calcResult').innerHTML=`<div class="score-big"><b>${Number.isFinite(r)?(Math.round(r*100)/100):'—'}</b><span>${d[2]}</span></div>`}}
function openScales(){modal(`<div class="modal-head"><h2>Escalas</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="list">${[['glasgow','Glasgow'],['barthel','Barthel'],['norton','Norton'],['braden','Braden'],['eva','EVA del dolor']].map(x=>`<button class="list-row clickable" data-scale="${x[0]}"><div class="avatar">◎</div><div class="grow"><strong>${x[1]}</strong></div><span class="chev">›</span></button>`).join('')}</div><div class="notice">Comprueba que la versión de la escala coincide con la utilizada por tu centro y aplica sus instrucciones oficiales.</div>`);$$('[data-scale]').forEach(b=>b.onclick=()=>openScale(b.dataset.scale))}
function openScale(type){if(type==='glasgow')return scoreScale('Glasgow',[['Ocular',[['Espontánea',4],['A la voz',3],['Al dolor',2],['Ninguna',1]]],['Verbal',[['Orientada',5],['Confusa',4],['Palabras inapropiadas',3],['Sonidos incomprensibles',2],['Ninguna',1]]],['Motora',[['Obedece órdenes',6],['Localiza dolor',5],['Retirada',4],['Flexión anormal',3],['Extensión',2],['Ninguna',1]]]],v=>`${v}/15`);if(type==='norton')return scoreScale('Norton',[['Estado físico',[['Bueno',4],['Mediano',3],['Regular',2],['Muy malo',1]]],['Estado mental',[['Alerta',4],['Apático',3],['Confuso',2],['Estupor',1]]],['Actividad',[['Ambulante',4],['Camina con ayuda',3],['Sentado',2],['Encamado',1]]],['Movilidad',[['Total',4],['Disminuida',3],['Muy limitada',2],['Inmóvil',1]]],['Incontinencia',[['Ninguna',4],['Ocasional',3],['Urinaria',2],['Doble',1]]]],v=>`${v} puntos`);if(type==='eva')return modal(`<div class="modal-head"><h2>EVA del dolor</h2><button class="icon-btn" onclick="closeModal()">×</button></div><label>Intensidad 0–10</label><input id="evaRange" type="range" min="0" max="10" value="0" style="width:100%"><div class="score-big"><b id="evaVal">0</b><span>0 = sin dolor · 10 = máximo dolor imaginable</span></div>`),$('#evaRange').oninput=e=>$('#evaVal').textContent=e.target.value;if(type==='barthel')return scoreScale('Barthel',[['Comer',[['Independiente',10],['Necesita ayuda',5],['Dependiente',0]]],['Lavarse',[['Independiente',5],['Dependiente',0]]],['Vestirse',[['Independiente',10],['Necesita ayuda',5],['Dependiente',0]]],['Arreglarse',[['Independiente',5],['Dependiente',0]]],['Deposiciones',[['Continente',10],['Accidente ocasional',5],['Incontinente',0]]],['Micción',[['Continente',10],['Accidente ocasional',5],['Incontinente',0]]],['Retrete',[['Independiente',10],['Necesita ayuda',5],['Dependiente',0]]],['Traslado',[['Independiente',15],['Ayuda mínima',10],['Gran ayuda',5],['Incapaz',0]]],['Deambulación',[['Independiente',15],['Ayuda',10],['Silla de ruedas',5],['Incapaz',0]]],['Escaleras',[['Independiente',10],['Necesita ayuda',5],['Incapaz',0]]]],v=>`${v}/100`);if(type==='braden')return scoreScale('Braden',[['Percepción sensorial',[['Sin limitación',4],['Ligeramente limitada',3],['Muy limitada',2],['Completamente limitada',1]]],['Humedad',[['Raramente húmeda',4],['Ocasionalmente húmeda',3],['Muy húmeda',2],['Constantemente húmeda',1]]],['Actividad',[['Camina con frecuencia',4],['Camina ocasionalmente',3],['En silla',2],['Encamado',1]]],['Movilidad',[['Sin limitación',4],['Ligeramente limitada',3],['Muy limitada',2],['Completamente inmóvil',1]]],['Nutrición',[['Excelente',4],['Adecuada',3],['Probablemente inadecuada',2],['Muy pobre',1]]],['Fricción/cizallamiento',[['Sin problema',3],['Problema potencial',2],['Problema',1]]]],v=>`${v} puntos`)}
function scoreScale(title,items,fmt){modal(`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" onclick="closeModal()">×</button></div><form id="scaleForm">${items.map((it,i)=>`<label>${it[0]}</label><select class="field" name="s${i}">${it[1].map(([l,v])=>`<option value="${v}">${l} — ${v}</option>`).join('')}</select>`).join('')}<div id="scaleScore"></div><div class="modal-actions"><button class="btn primary">Calcular</button></div></form><div class="notice">Usa la interpretación oficial de tu centro; NurseFlow muestra el cálculo, no un diagnóstico.</div>`);$('#scaleForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const sum=items.reduce((n,_,i)=>n+Number(f.get(`s${i}`)),0);$('#scaleScore').innerHTML=`<div class="score-big"><b>${fmt(sum)}</b></div>`}}
function openLabs(){modal(`<div class="modal-head"><h2>Analíticas</h2><button class="icon-btn" onclick="closeModal()">×</button></div><input class="field" id="labQ" placeholder="Buscar Hb, sodio, creatinina…"><div id="labList" class="list" style="margin-top:12px">${NURSE_DATA.labs.map(labRow).join('')}</div><div class="notice">Los rangos pueden variar por laboratorio, técnica, edad, sexo y situación clínica. Comprueba siempre el rango del informe real.</div>`);$('#labQ').oninput=e=>{$$('#labList .list-row').forEach(x=>x.classList.toggle('hidden',!x.textContent.toLowerCase().includes(e.target.value.toLowerCase())))}}
function labRow(x){return `<div class="list-row"><div class="avatar">${esc(x[1])}</div><div class="grow"><strong>${esc(x[0])}</strong><div class="sub">${esc(x[3])} ${x[2]?'· '+esc(x[2]):''}</div></div><span class="pill">${esc(x[4])}</span></div>`}
function openDictionary(){modal(`<div class="modal-head"><h2>Diccionario hospitalario</h2><button class="icon-btn" onclick="closeModal()">×</button></div><input class="field" id="dictQ" placeholder="Buscar abreviatura o término…"><div id="dictList" class="list" style="margin-top:12px">${NURSE_DATA.glossary.map(x=>`<div class="list-row"><div class="avatar">${esc(x[0])}</div><div class="grow"><strong>${esc(x[0])}</strong><div class="sub">${esc(x[1])}</div></div></div>`).join('')}</div>`);$('#dictQ').oninput=e=>{$$('#dictList .list-row').forEach(x=>x.classList.toggle('hidden',!x.textContent.toLowerCase().includes(e.target.value.toLowerCase())))}}
async function openICDLookup(query='',onSelect=null){modal(`<div class="modal-head"><h2>CIE-11</h2><button class="icon-btn" onclick="closeModal()">×</button></div><label>Buscar diagnóstico</label><div class="form-row"><input class="field" id="icdQ" value="${esc(query)}"><button class="btn primary" id="icdSearch">Buscar</button></div><div id="icdResults" style="margin-top:12px"></div><div class="notice info">La API oficial de la OMS requiere OAuth2. Configura la URL de tu Worker gratuito en Ajustes. Sin Worker, puedes escribir el diagnóstico manualmente en el diario.</div>`);$('#icdSearch').onclick=async()=>{const q=$('#icdQ').value.trim();if(!q)return;const box=$('#icdResults');box.innerHTML='<div class="empty">Buscando…</div>';if(!state.settings.icdWorker){box.innerHTML='<div class="notice">Falta configurar el Worker de CIE-11 en Ajustes.</div>';return}try{const r=await fetch(`${state.settings.icdWorker.replace(/\/$/,'')}/icd/search?q=${encodeURIComponent(q)}`);if(!r.ok)throw new Error();const data=await r.json();const arr=data.destinationEntities||data.results||data||[];box.innerHTML=`<div class="list">${arr.slice(0,20).map((x,i)=>{const code=x.theCode||x.code||'';const title=(x.title||x.bestMatchText||'').replace(/<[^>]*>/g,'');return `<button class="list-row clickable" data-icd="${i}"><span class="pill">${esc(code||'CIE')}</span><div class="grow"><strong>${esc(title)}</strong></div></button>`}).join('')||noData('Sin resultados')}</div>`;$$('[data-icd]').forEach(b=>b.onclick=()=>{const x=arr[+b.dataset.icd],sel={code:x.theCode||x.code||'',title:(x.title||x.bestMatchText||'').replace(/<[^>]*>/g,'')};if(onSelect){closeModal();onSelect(sel)}else toast(`${sel.code} ${sel.title}`)})}catch{box.innerHTML='<div class="notice">No se pudo consultar CIE-11. Comprueba la URL del Worker y la conexión.</div>'}};if(query)setTimeout(()=>$('#icdSearch').click(),50)}

async function renderStudy(){
  setTitle('Estudio','Repaso inteligente'); const [cards,quiz,cases]=await Promise.all([NurseDB.all('flashcards'),NurseDB.all('quiz'),NurseDB.all('cases')]); const due=cards.filter(c=>!c.due||c.due<=isoToday()); const reviews=[...new Set(cases.flatMap(c=>[c.review,...(c.meds||[]),c.diagnosis].filter(Boolean)))];
  $('#app').innerHTML=`<div class="card hero"><p class="small muted">Repaso de hoy</p><h2>${due.length} flashcards pendientes</h2><p>${reviews.length} temas procedentes de prácticas</p><button class="btn secondary" id="startReview">Empezar repaso</button></div><div class="grid-2"><button class="quick" id="flashBtn"><span class="ico">◫</span><div><strong>Flashcards</strong><small>${cards.length} tarjetas</small></div></button><button class="quick" id="quizBtn"><span class="ico">?</span><div><strong>Pre-EIR</strong><small>${quiz.length} preguntas originales</small></div></button><button class="quick" id="practiceReview"><span class="ico">↺</span><div><strong>De mis prácticas</strong><small>Patologías y dudas para revisar</small></div></button><button class="quick" id="studyStats"><span class="ico">↗</span><div><strong>Progreso</strong><small>Actividad de estudio</small></div></button></div>${section('Temas vistos en prácticas')}<div class="tag-cloud">${reviews.slice(0,20).map(x=>`<span class="tag">${esc(x)}</span>`).join('')||'<span class="muted small">Aparecerán al registrar casos.</span>'}</div>`;
  $('#startReview').onclick=()=>openFlashReview();$('#flashBtn').onclick=openFlashcards;$('#quizBtn').onclick=openQuiz;$('#practiceReview').onclick=()=>openPracticeReview(reviews);$('#studyStats').onclick=openStudyStats;
}
async function openFlashcards(){const rows=await NurseDB.all('flashcards');modal(`<div class="modal-head"><h2>Flashcards</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="list">${rows.map(x=>`<div class="list-row"><div class="grow"><strong>${esc(x.q)}</strong><div class="sub">${esc(x.topic||'General')} · próxima ${x.due?dateFmt(x.due):'hoy'}</div></div><button class="icon-btn" data-del-card="${x.id}">×</button></div>`).join('')||noData('Sin tarjetas')}</div><form id="cardForm"><label>Pregunta</label><input class="field" name="q" required><label>Respuesta</label><textarea class="field" name="a" required></textarea><label>Tema</label><input class="field" name="topic"><div class="modal-actions"><button type="button" class="btn" id="reviewCards">Repasar</button><button class="btn primary">Añadir</button></div></form>`);$('#cardForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await NurseDB.put('flashcards',{id:uid(),q:f.get('q').trim(),a:f.get('a').trim(),topic:f.get('topic').trim()||'General',due:isoToday(),ease:2.5,interval:0,reps:0});closeModal();openFlashcards()};$$('[data-del-card]').forEach(b=>b.onclick=async()=>{await NurseDB.remove('flashcards',b.dataset.delCard);closeModal();openFlashcards()});$('#reviewCards').onclick=()=>{closeModal();openFlashReview()}}
async function openFlashReview(){let cards=(await NurseDB.all('flashcards')).filter(c=>!c.due||c.due<=isoToday());if(!cards.length)return toast('No hay tarjetas pendientes');let i=0;const show=()=>{const c=cards[i];modal(`<div class="modal-head"><h2>Repaso ${i+1}/${cards.length}</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="card"><p class="small muted">${esc(c.topic||'General')}</p><h2>${esc(c.q)}</h2><div id="answer" class="hidden"><div class="divider"></div><p>${esc(c.a)}</p></div></div><button class="btn block" id="showAnswer">Mostrar respuesta</button><div id="rating" class="grid-3 hidden" style="margin-top:10px"><button class="btn" data-rate="again">Otra vez</button><button class="btn" data-rate="good">Bien</button><button class="btn primary" data-rate="easy">Fácil</button></div>`);$('#showAnswer').onclick=()=>{$('#answer').classList.remove('hidden');$('#rating').classList.remove('hidden');$('#showAnswer').classList.add('hidden');$$('[data-rate]').forEach(b=>b.onclick=async()=>{const rate=b.dataset.rate;c.reps=(c.reps||0)+1;if(rate==='again'){c.interval=0;c.due=isoToday()}if(rate==='good'){c.interval=Math.max(1,Math.round((c.interval||1)*1.8));c.due=addDays(c.interval)}if(rate==='easy'){c.interval=Math.max(3,Math.round((c.interval||1)*2.5));c.due=addDays(c.interval)}await NurseDB.put('flashcards',c);i++;if(i>=cards.length){closeModal();toast('Repaso completado')}else show()})}};show()}
function addDays(n){const d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
async function openQuiz(){const qs=await NurseDB.all('quiz');let i=0,score=0;const show=()=>{const q=qs[i];modal(`<div class="modal-head"><h2>Pre-EIR · ${i+1}/${qs.length}</h2><button class="icon-btn" onclick="closeModal()">×</button></div><span class="pill">${esc(q.topic)}</span><h3>${esc(q.q)}</h3><div id="options">${q.o.map((x,j)=>`<button class="quiz-option" data-opt="${j}">${esc(x)}</button>`).join('')}</div><div id="quizExplain"></div>`);$$('[data-opt]').forEach(b=>b.onclick=()=>{const j=+b.dataset.opt;$$('[data-opt]').forEach((x,k)=>{x.disabled=true;if(k===q.a)x.classList.add('correct');if(k===j&&j!==q.a)x.classList.add('wrong')});if(j===q.a)score++;$('#quizExplain').innerHTML=`<div class="notice info" style="margin-top:10px">${esc(q.e)}</div><button class="btn primary block" id="nextQuiz" style="margin-top:10px">${i===qs.length-1?'Ver resultado':'Siguiente'}</button>`;$('#nextQuiz').onclick=()=>{i++;if(i>=qs.length){modal(`<div class="modal-head"><h2>Resultado</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="score-big"><b>${score}/${qs.length}</b><span>${Math.round(score/qs.length*100)}%</span></div><p class="small muted">Banco de preguntas originales de práctica; no son preguntas oficiales del EIR.</p>`)}else show()}})};show()}
function openPracticeReview(items){modal(`<div class="modal-head"><h2>De mis prácticas</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="tag-cloud">${items.map(x=>`<button class="tag" data-create-card="${esc(x)}">${esc(x)}</button>`).join('')||'<span class="muted">No hay temas todavía.</span>'}</div><p class="small muted">Toca un tema para crear una flashcard a partir de él.</p>`);$$('[data-create-card]').forEach(b=>b.onclick=async()=>{await NurseDB.put('flashcards',{id:uid(),q:`Repasar: ${b.dataset.createCard}`,a:'Completa esta tarjeta con tus apuntes o una fuente académica fiable.',topic:'Prácticum',due:isoToday(),ease:2.5,interval:0,reps:0});b.classList.add('active');toast('Flashcard creada')})}
async function openStudyStats(){const cards=await NurseDB.all('flashcards');modal(`<div class="modal-head"><h2>Progreso de estudio</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="metric-row"><div class="metric"><b>${cards.length}</b><span>tarjetas</span></div><div class="metric"><b>${cards.filter(c=>c.reps>0).length}</b><span>repasadas</span></div><div class="metric"><b>${cards.filter(c=>c.due>isoToday()).length}</b><span>al día</span></div><div class="metric"><b>${new Set(cards.map(c=>c.topic)).size}</b><span>temas</span></div></div>`)}

async function openGlobalSearch(){modal(`<div class="modal-head"><h2>Buscar en NurseFlow</h2><button class="icon-btn" onclick="closeModal()">×</button></div><input class="field" id="globalQ" autofocus placeholder="Medicamento, técnica, caso, abreviatura…"><div id="globalResults"></div>`);$('#globalQ').oninput=async e=>{const q=e.target.value.trim().toLowerCase();if(q.length<2)return $('#globalResults').innerHTML='';const [cases,procs,meds,cards]=await Promise.all([NurseDB.all('cases'),NurseDB.all('procedures'),NurseDB.all('meds'),NurseDB.all('flashcards')]);const out=[];procs.filter(x=>x.name.toLowerCase().includes(q)).slice(0,5).forEach(x=>out.push(`<button class="list-row clickable" data-gproc="${x.id}"><span class="pill">Técnica</span><div class="grow"><strong>${esc(x.name)}</strong></div></button>`));cases.filter(x=>`${x.diagnosis} ${x.learning} ${x.review}`.toLowerCase().includes(q)).slice(0,5).forEach(x=>out.push(`<button class="list-row clickable" data-gcase="${x.id}"><span class="pill">Caso</span><div class="grow"><strong>${esc(x.diagnosis)}</strong><div class="sub">${dateFmt(x.date)}</div></div></button>`));meds.filter(x=>x.name.toLowerCase().includes(q)).slice(0,5).forEach(x=>out.push(`<button class="list-row clickable" data-gmed="${x.id}"><span class="pill">Rx</span><div class="grow"><strong>${esc(x.name)}</strong></div></button>`));NURSE_DATA.glossary.filter(x=>`${x[0]} ${x[1]}`.toLowerCase().includes(q)).slice(0,5).forEach(x=>out.push(`<div class="list-row"><span class="pill">Diccionario</span><div class="grow"><strong>${esc(x[0])}</strong><div class="sub">${esc(x[1])}</div></div></div>`));cards.filter(x=>`${x.q} ${x.a}`.toLowerCase().includes(q)).slice(0,5).forEach(x=>out.push(`<div class="list-row"><span class="pill">Estudio</span><div class="grow"><strong>${esc(x.q)}</strong></div></div>`));$('#globalResults').innerHTML=`<div class="list" style="margin-top:12px">${out.join('')||noData('Sin resultados locales')}</div>`;$$('[data-gproc]').forEach(b=>b.onclick=()=>{closeModal();openProcedure(b.dataset.gproc)});$$('[data-gcase]').forEach(b=>b.onclick=()=>{closeModal();openCaseDetail(b.dataset.gcase)});$$('[data-gmed]').forEach(b=>b.onclick=()=>{closeModal();openMedDetail(b.dataset.gmed)})}}

async function openSettings(){modal(`<div class="modal-head"><h2>Ajustes</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="list"><button class="list-row clickable" id="setProfile"><div class="avatar">☺</div><div class="grow"><strong>Perfil académico</strong><div class="sub">Universidad, curso y asignaturas</div></div><span class="chev">›</span></button><button class="list-row clickable" id="setPracticum"><div class="avatar">✚</div><div class="grow"><strong>Prácticas</strong><div class="sub">Centro, periodo y servicio</div></div><span class="chev">›</span></button><button class="list-row clickable" id="setAppearance"><div class="avatar">◐</div><div class="grow"><strong>Apariencia</strong><div class="sub">Tema claro, oscuro o sistema</div></div><span class="chev">›</span></button><button class="list-row clickable" id="setPrivacy"><div class="avatar">⌁</div><div class="grow"><strong>Privacidad y bloqueo</strong><div class="sub">PIN, biometría y autobloqueo</div></div><span class="chev">›</span></button><button class="list-row clickable" id="setApis"><div class="avatar">API</div><div class="grow"><strong>APIs y fuentes</strong><div class="sub">CIMA / CIE-11 / Worker</div></div><span class="chev">›</span></button><button class="list-row clickable" id="setData"><div class="avatar">⇩</div><div class="grow"><strong>Datos y backup</strong><div class="sub">Exportar, importar y restablecer</div></div><span class="chev">›</span></button><button class="list-row clickable" id="setOffline"><div class="avatar">✓</div><div class="grow"><strong>Offline e instalación</strong><div class="sub">Estado de PWA y almacenamiento</div></div><span class="chev">›</span></button><button class="list-row clickable" id="setAbout"><div class="avatar">i</div><div class="grow"><strong>Acerca de</strong><div class="sub">Fuentes, límites y versión</div></div><span class="chev">›</span></button></div>`);$('#setProfile').onclick=()=>{closeModal();openProfileSettings()};$('#setPracticum').onclick=()=>{closeModal();openPracticumSettings()};$('#setAppearance').onclick=()=>{closeModal();openAppearanceSettings()};$('#setPrivacy').onclick=()=>{closeModal();openPrivacySettings()};$('#setApis').onclick=()=>{closeModal();openApiSettings()};$('#setData').onclick=()=>{closeModal();openDataSettings()};$('#setOffline').onclick=()=>{closeModal();openOfflineSettings()};$('#setAbout').onclick=()=>{closeModal();openAbout()}}
function openProfileSettings(){
  const subjects=NURSE_DATA.ucv.subjects[String(state.settings.courseNumber)]||[],selected=new Set(state.settings.selectedSubjects||[]),subjectHtml=subjects.map(([code,name,semester])=>`<label class="subject-check"><input type="checkbox" name="subjects" value="${esc(code)}" ${selected.has(code)?'checked':''}><span><strong>${esc(name)}</strong><small>${semester==='Anual'?'Anual':`Semestre ${semester}`}</small></span></label>`).join('');
  modal(`<div class="modal-head"><h2>Perfil académico</h2><button class="icon-btn" onclick="closeModal()">×</button></div><form id="profileForm"><label>Nombre</label><input class="field" name="name" value="${esc(state.settings.profileName)}" placeholder="Opcional"><label>Universidad</label><select class="field" name="university"><option value="UCV" ${state.settings.university==='UCV'?'selected':''}>Universidad Católica de Valencia (UCV)</option><option value="other" ${state.settings.university!=='UCV'?'selected':''}>Otra universidad</option></select><label>Curso</label><select class="field" name="course" id="profileCourse">${[1,2,3,4].map(n=>`<option value="${n}" ${String(n)===String(state.settings.courseNumber)?'selected':''}>${n}º Enfermería</option>`).join('')}</select><label>Asignaturas</label><div class="subject-picker">${subjectHtml}</div><div class="modal-actions"><button class="btn primary">Guardar</button></div></form>`);
  $('#profileCourse').onchange=async e=>{state.settings.courseNumber=e.target.value;state.settings.course=`${e.target.value}º Enfermería`;state.settings.selectedSubjects=[];await saveSettings();closeModal();openProfileSettings()};
  $('#profileForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);state.settings.profileName=f.get('name').trim();state.settings.university=f.get('university');state.settings.courseNumber=String(f.get('course'));state.settings.course=`${f.get('course')}º Enfermería`;state.settings.selectedSubjects=f.getAll('subjects');await saveSettings();closeModal();render();toast('Perfil actualizado')};
}
function openAppearanceSettings(){modal(`<div class="modal-head"><h2>Apariencia</h2><button class="icon-btn" onclick="closeModal()">×</button></div><label>Tema</label><select class="field" id="themeSelect"><option value="system" ${state.settings.theme==='system'?'selected':''}>Seguir sistema</option><option value="light" ${state.settings.theme==='light'?'selected':''}>Claro</option><option value="dark" ${state.settings.theme==='dark'?'selected':''}>Oscuro</option></select><label class="switch-row"><span><strong>Advertencias clínicas</strong><span class="sub">Mostrar recordatorios de verificación</span></span><span class="switch"><input id="warnSwitch" type="checkbox" ${state.settings.showClinicalWarnings?'checked':''}><span class="slider"></span></span></label><div class="modal-actions"><button class="btn primary" id="saveAppearance">Guardar</button></div>`);$('#saveAppearance').onclick=async()=>{state.settings.theme=$('#themeSelect').value;state.settings.showClinicalWarnings=$('#warnSwitch').checked;await saveSettings();closeModal();render();toast('Apariencia actualizada')}}
async function hashText(s){const b=new TextEncoder().encode(s);const h=await crypto.subtle.digest('SHA-256',b);return [...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function openPrivacySettings(){modal(`<div class="modal-head"><h2>Privacidad y bloqueo</h2><button class="icon-btn" onclick="closeModal()">×</button></div><label class="switch-row"><span><strong>Bloquear al abrir</strong><span class="sub">Protege el acceso a la PWA</span></span><span class="switch"><input id="lockSwitch" type="checkbox" ${state.settings.lockEnabled?'checked':''}><span class="slider"></span></span></label><label>Método</label><select id="lockMethod" class="field"><option value="pin" ${state.settings.lockMethod==='pin'?'selected':''}>PIN</option><option value="webauthn" ${state.settings.lockMethod==='webauthn'?'selected':''}>Biometría / código del dispositivo (WebAuthn)</option></select><label>Nuevo PIN (4–8 cifras)</label><input class="field" id="newPin" inputmode="numeric" maxlength="8" placeholder="Déjalo vacío para conservarlo"><label>Autobloqueo</label><select class="field" id="autoLock"><option value="0">Nunca mientras siga abierta</option><option value="1" ${state.settings.autoLock==1?'selected':''}>1 minuto</option><option value="5" ${state.settings.autoLock==5?'selected':''}>5 minutos</option><option value="15" ${state.settings.autoLock==15?'selected':''}>15 minutos</option></select><div class="notice info">El bloqueo protege frente al acceso casual en este dispositivo. Mantén el diario anonimizado aunque uses PIN o biometría.</div><div class="modal-actions"><button class="btn primary" id="savePrivacy">Guardar</button></div>`);$('#savePrivacy').onclick=async()=>{const enabled=$('#lockSwitch').checked,method=$('#lockMethod').value,pin=$('#newPin').value.trim();if(enabled&&method==='pin'&&!state.settings.pinHash&&!/^\d{4,8}$/.test(pin))return toast('Configura un PIN de 4 a 8 cifras');if(pin){if(!/^\d{4,8}$/.test(pin))return toast('PIN no válido');state.settings.pinHash=await hashText(pin)}if(enabled&&method==='webauthn'){const ok=await enrollWebAuthn();if(!ok)return}state.settings.lockEnabled=enabled;state.settings.lockMethod=method;state.settings.autoLock=+$('#autoLock').value;await saveSettings();closeModal();toast('Privacidad actualizada')}}
async function enrollWebAuthn(){if(!window.PublicKeyCredential||!navigator.credentials)return toast('WebAuthn no está disponible'),false;try{const challenge=crypto.getRandomValues(new Uint8Array(32)),userId=crypto.getRandomValues(new Uint8Array(16));const cred=await navigator.credentials.create({publicKey:{challenge,rp:{name:'NurseFlow'},user:{id:userId,name:'nurseflow-local',displayName:'NurseFlow local'},pubKeyCredParams:[{alg:-7,type:'public-key'},{alg:-257,type:'public-key'}],authenticatorSelection:{userVerification:'required',residentKey:'preferred'},timeout:60000,attestation:'none'}});state.settings.credentialId=btoa(String.fromCharCode(...new Uint8Array(cred.rawId)));return true}catch(e){toast('No se pudo activar la biometría/código del dispositivo');return false}}
function showLock(){const l=$('#appLock');l.classList.remove('hidden');l.innerHTML=`<div class="lock-card"><div class="lock-icon">⌁</div><h2>NurseFlow bloqueado</h2><p>${state.settings.lockMethod==='webauthn'?'Usa la autenticación del dispositivo para continuar.':'Introduce tu PIN.'}</p>${state.settings.lockMethod==='pin'?'<div id="pinDots" class="pin-dots"></div><div class="pin-grid">'+[1,2,3,4,5,6,7,8,9,'←',0,'✓'].map(x=>`<button data-pin="${x}">${x}</button>`).join('')+'</div>':'<button class="btn primary block" id="bioUnlock">Desbloquear</button>'}</div>`;if(state.settings.lockMethod==='pin'){let pin='';const draw=()=>$('#pinDots').textContent='•'.repeat(pin.length);$$('[data-pin]').forEach(b=>b.onclick=async()=>{const v=b.dataset.pin;if(v==='←')pin=pin.slice(0,-1);else if(v==='✓'){if(await hashText(pin)===state.settings.pinHash)unlockApp();else{pin='';toast('PIN incorrecto')}}else if(pin.length<8)pin+=v;draw()})}else $('#bioUnlock').onclick=webAuthnUnlock}
async function webAuthnUnlock(){try{const raw=Uint8Array.from(atob(state.settings.credentialId||''),c=>c.charCodeAt(0));await navigator.credentials.get({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),allowCredentials:[{type:'public-key',id:raw}],userVerification:'required',timeout:60000}});unlockApp()}catch{toast('No se pudo autenticar')}}
function unlockApp(){state.unlocked=true;state.lastActive=Date.now();$('#appLock').classList.add('hidden');render()}
function openApiSettings(){modal(`<div class="modal-head"><h2>APIs y fuentes</h2><button class="icon-btn" onclick="closeModal()">×</button></div><label>Acceso a CIMA / AEMPS</label><select class="field" id="apiMode"><option value="direct" ${state.settings.apiMode==='direct'?'selected':''}>Directo desde la PWA</option><option value="worker" ${state.settings.apiMode==='worker'?'selected':''}>A través del Worker</option></select><label>URL del Cloudflare Worker</label><input class="field" id="workerUrl" value="${esc(state.settings.icdWorker)}" placeholder="https://nurseflow-api.tuusuario.workers.dev"><div class="notice info">El Worker es opcional para CIMA y necesario para CIE-11 si quieres mantener las credenciales OMS fuera del navegador. La ficha de medicamentos usa medicamento, ficha técnica segmentada, notas y materiales de seguridad de CIMA.</div><div class="modal-actions"><button class="btn" id="testWorker">Probar</button><button class="btn primary" id="saveApis">Guardar</button></div>`);$('#saveApis').onclick=async()=>{state.settings.apiMode=$('#apiMode').value;state.settings.icdWorker=$('#workerUrl').value.trim().replace(/\/$/,'');await saveSettings();closeModal();toast('APIs actualizadas')};$('#testWorker').onclick=async()=>{const u=$('#workerUrl').value.trim().replace(/\/$/,'');if(!u)return toast('Introduce una URL');try{const r=await fetch(`${u}/health`);toast(r.ok?'Worker operativo':'El Worker respondió con error')}catch{toast('No se pudo conectar al Worker')}}}
async function openDataSettings(){const estimate=navigator.storage?.estimate?await navigator.storage.estimate():{};modal(`<div class="modal-head"><h2>Datos y backup</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="card compact"><strong>Almacenamiento local</strong><p class="small muted">Uso aproximado: ${estimate.usage?Math.round(estimate.usage/1024/1024*10)/10+' MB':'no disponible'}</p></div><div class="list"><button class="list-row clickable" id="exportData"><div class="avatar">⇩</div><div class="grow"><strong>Exportar copia</strong><div class="sub">JSON con todos los datos locales</div></div></button><button class="list-row clickable" id="importData"><div class="avatar">⇧</div><div class="grow"><strong>Importar copia</strong><div class="sub">Reemplaza los datos actuales</div></div></button><button class="list-row clickable" id="resetData"><div class="avatar danger-text">!</div><div class="grow"><strong class="danger-text">Restablecer app</strong><div class="sub">Elimina todos los datos locales</div></div></button></div>`);$('#exportData').onclick=exportBackup;$('#importData').onclick=()=>$('#fileImport').click();$('#resetData').onclick=async()=>{if(confirm('Se eliminarán todos los datos locales de NurseFlow. ¿Continuar?')){await NurseDB.reset();location.reload()}}}
async function exportBackup(){const payload=await NurseDB.exportAll();const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`nurseflow-backup-${isoToday()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia exportada')}
async function importBackupFile(e){const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(!confirm('La importación reemplazará los datos actuales. ¿Continuar?'))return;await NurseDB.importAll(data);location.reload()}catch{toast('Archivo de copia no válido')}finally{e.target.value=''}}
async function openOfflineSettings(){let persisted=false;try{persisted=await navigator.storage?.persisted?.()}catch{}modal(`<div class="modal-head"><h2>Offline e instalación</h2><button class="icon-btn" onclick="closeModal()">×</button></div><div class="list"><div class="list-row"><div class="avatar">${navigator.onLine?'✓':'×'}</div><div class="grow"><strong>${navigator.onLine?'Con conexión':'Modo offline'}</strong><div class="sub">La base local y las herramientas siguen funcionando.</div></div></div><div class="list-row"><div class="avatar">${'serviceWorker'in navigator?'✓':'×'}</div><div class="grow"><strong>Service Worker</strong><div class="sub">${'serviceWorker'in navigator?'Compatible':'No compatible'}</div></div></div><div class="list-row"><div class="avatar">${persisted?'✓':'·'}</div><div class="grow"><strong>Almacenamiento persistente</strong><div class="sub">${persisted?'Concedido':'No confirmado'}</div></div></div></div><div class="modal-actions"><button class="btn" id="askPersist">Solicitar persistencia</button></div>`);$('#askPersist').onclick=async()=>{try{const ok=await navigator.storage.persist();toast(ok?'Persistencia concedida':'El navegador no la concedió')}catch{toast('No disponible')}}}
function openAbout(){modal(`<div class="modal-head"><h2>Acerca de NurseFlow</h2><button class="icon-btn" onclick="closeModal()">×</button></div><p><strong>Versión 2.0.0</strong></p><p class="small muted">PWA local-first para organización académica, prácticas y estudio de Enfermería.</p><h3>Fuentes</h3><div class="list"><div class="list-row"><div class="grow"><strong>CIMA / AEMPS</strong><div class="sub">Medicamentos, ficha técnica segmentada, notas y materiales de seguridad.</div></div></div><div class="list-row"><div class="grow"><strong>OMS CIE-11</strong><div class="sub">Consulta opcional mediante API oficial.</div></div></div><div class="list-row"><div class="grow"><strong>UCV</strong><div class="sub">Asignaturas del Grado en Enfermería usadas para facilitar la configuración del horario.</div></div></div></div><h3>Privacidad</h3><p class="small muted">Horario, tareas, casos, procedimientos, notas y fichas guardadas se almacenan localmente en el navegador. No introduzcas datos identificativos de pacientes.</p><h3>Uso clínico</h3><p class="small muted">La vista de CIMA reorganiza información oficial para consulta rápida, pero no sustituye la prescripción, la ficha técnica vigente, los protocolos del centro ni la supervisión correspondiente.</p>`)}

window.closeModal=closeModal; window.openCaseDetail=openCaseDetail; window.openProcedure=openProcedure;
